  ensureShadowStyles(shadow);

  // ===================== v0.9.91 Audi A3 / TT twin-dial cluster (panel DOM) =====================
  const AUD_REACH=.30;                       // needle tip = inner end of the major tick + 30 % of its length (same rule as every other skin)
  const audRad=d=>d*Math.PI/180;
  const audXY=(cx,cy,r,deg)=>[cx+r*Math.sin(audRad(deg)),cy-r*Math.cos(audRad(deg))];
  const audN=v=>(Math.round(v*100)/100).toString();
  function audArc(cx,cy,r,a0,a1){
    const [x0,y0]=audXY(cx,cy,r,a0),[x1,y1]=audXY(cx,cy,r,a1);
    return `M${audN(x0)} ${audN(y0)} A${r} ${r} 0 ${(a1-a0)>180?1:0} 1 ${audN(x1)} ${audN(y1)}`;
  }
  /* Ticks + numerals (+ red band). c = {cx,cy,rOut,majLen,minLen,rNum,fs,start,sweep,majorCount,minorPer,label,redFrom} */
  function audDialMarkup(c){
    const total=c.majorCount*c.minorPer;let out='',nums='';
    for(let i=0;i<=total;i++){
      const f=i/total,deg=c.start+c.sweep*f,major=i%c.minorPer===0,red=c.redFrom!=null&&f>=c.redFrom-1e-9;
      const [x1,y1]=audXY(c.cx,c.cy,c.rOut-(major?c.majLen:c.minLen),deg),[x2,y2]=audXY(c.cx,c.cy,c.rOut,deg);
      out+=`<line class="aud-tick${major?' maj':''}${red?' red':''}" x1="${audN(x1)}" y1="${audN(y1)}" x2="${audN(x2)}" y2="${audN(y2)}"/>`;
      if(major){
        const [tx,ty]=audXY(c.cx,c.cy,c.rNum,deg);
        nums+=`<text class="aud-num${red?' red':''}" x="${audN(tx)}" y="${audN(ty)}" style="font-size:${c.fs}px">${c.label(i/c.minorPer)}</text>`;
      }
    }
    if(c.redFrom!=null)out+=`<path class="aud-redarc" d="${audArc(c.cx,c.cy,c.rOut+(c.redGap||4),c.start+c.sweep*c.redFrom,c.start+c.sweep)}"/>`;
    return out+nums;
  }
  /* Face + two interchangeable rings: chrome (A3) and turned / brushed aluminium (TT). */
  function audFaceMarkup(cx,cy,R,w){
    const face=`<circle cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="url(#aud-face)"/>`;
    const chrome=`<g class="aud-ring-chrome"><circle cx="${cx}" cy="${cy}" r="${R-w/2}" fill="none" stroke="url(#aud-chrome)" stroke-width="${w}"/>`+
      `<circle cx="${cx}" cy="${cy}" r="${R-.5}" fill="none" stroke="#0b0c0d" stroke-width="1"/><circle cx="${cx}" cy="${cy}" r="${R-w+.4}" fill="none" stroke="#1d1e21" stroke-width="1"/>`+
      `<path d="${audArc(cx,cy,R-w/2,-155,-55)}" fill="none" stroke="#fff" stroke-opacity=".75" stroke-width="${(w*.28).toFixed(1)}" stroke-linecap="round"/></g>`;
    const n=Math.max(6,Math.round(w)),step=w/n;let lines='';
    for(let i=0;i<n;i++){const g=132+((i*37+11)%7)*13;lines+=`<circle cx="${cx}" cy="${cy}" r="${(R-w+(i+.5)*step).toFixed(2)}" fill="none" stroke="rgb(${g},${g+3},${g+8})" stroke-width="${(step+.25).toFixed(2)}"/>`;}
    const metal=`<g class="aud-ring-metal">${lines}<circle cx="${cx}" cy="${cy}" r="${R-w/2}" fill="none" stroke="url(#aud-sheen)" stroke-width="${w}"/>`+
      `<circle cx="${cx}" cy="${cy}" r="${R-.5}" fill="none" stroke="#17181a" stroke-width="1"/><circle cx="${cx}" cy="${cy}" r="${R-w+.4}" fill="none" stroke="#141517" stroke-width="1"/></g>`;
    return face+chrome+metal;
  }
  function audNeedleMarkup(id,cx,cy,L,wT,tail,startDeg){
    const p=pts=>pts.map(q=>q[0].toFixed(2)+','+q[1].toFixed(2)).join(' ');
    const pt=[[-wT,tail],[-wT*.62,-L*.62],[0,-L],[wT*.62,-L*.62],[wT,tail]];                 // TT: sharp spike
    const sw=wT*.9,b=wT*.72,yb=-(L-sw/2-b);                                                  // A3: domed tip, outer tip lands exactly on L
    const rd=`M${(-wT*.95).toFixed(2)} ${tail} L${(-b).toFixed(2)} ${yb.toFixed(2)} A${b.toFixed(2)} ${b.toFixed(2)} 0 0 1 ${b.toFixed(2)} ${yb.toFixed(2)} L${(wT*.95).toFixed(2)} ${tail} Z`;
    return `<g id="${id}" class="aud-needle" transform="rotate(${startDeg} ${cx} ${cy})"><g transform="translate(${cx} ${cy})">`+
      `<polygon class="aud-n-pt" points="${p(pt)}"/><path class="aud-n-rd" d="${rd}" stroke-width="${sw.toFixed(2)}"/></g></g>`;
  }
  const audHub=(cx,cy,r,ring)=>`<circle class="aud-hub" cx="${cx}" cy="${cy}" r="${r}" stroke-width="${ring}"/><circle class="aud-hub-in" cx="${cx}" cy="${cy}" r="${(r*.42).toFixed(1)}"/>`;
  const AUD_BIG={cx:200,cy:200,R:200,ring:14,rOut:172,majLen:18,minLen:10,rNum:128};
  const AUD_SML={cx:58,cy:58,R:58,ring:7,rOut:46,majLen:9,minLen:5,rNum:27};
