      <linearGradient id="aud-chrome" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fbfcfd"/><stop offset=".16" stop-color="#8c9198"/><stop offset=".3" stop-color="#eef1f4"/><stop offset=".48" stop-color="#34373c"/><stop offset=".64" stop-color="#d4d9de"/><stop offset=".8" stop-color="#6d727a"/><stop offset="1" stop-color="#fdfdfe"/></linearGradient>
