      <linearGradient id="aud-plastic" x1="0" y1="0" x2=".7" y2="1"><stop offset="0" stop-color="#2e3034"/><stop offset=".18" stop-color="#17181b"/><stop offset=".62" stop-color="#0e0f11"/><stop offset="1" stop-color="#050506"/></linearGradient>
