  // ===================== v0.9.94 Nissan 350Z / Infiniti G35 triple-dial cluster (panel DOM) =====================
  const NIS_REACH=.30;                       // needle tip = inner end of the major tick + 30 % of its length (same rule as every other skin)
  const nisRad=d=>d*Math.PI/180;
  const nisXY=(cx,cy,r,deg)=>[cx+r*Math.sin(nisRad(deg)),cy-r*Math.cos(nisRad(deg))];
  const nisN=v=>(Math.round(v*100)/100).toString();
  function nisArc(cx,cy,r,a0,a1){
    const [x0,y0]=nisXY(cx,cy,r,a0),[x1,y1]=nisXY(cx,cy,r,a1);
    return `M${nisN(x0)} ${nisN(y0)} A${r} ${r} 0 ${Math.abs(a1-a0)>180?1:0} 1 ${nisN(x1)} ${nisN(y1)}`;
  }
  /* Ticks (major / mid / minor) + numerals + red arc + decorative band. c = {cx,cy,rOut,majLen,midLen,minLen,rNum,fs,start,sweep,majorCount,minorPer,label,redFrom,band} */
  function nisDialMarkup(c){
    const total=c.majorCount*c.minorPer,half=(c.minorPer>=4&&c.minorPer%2===0)?c.minorPer/2:0;
    let out='',nums='';
    for(let i=0;i<=total;i++){
      const f=i/total,deg=c.start+c.sweep*f,major=i%c.minorPer===0,mid=!major&&half>0&&i%half===0,red=c.redFrom!=null&&f>=c.redFrom-1e-9;
      const len=major?c.majLen:mid?c.midLen:c.minLen;
      const [x1,y1]=nisXY(c.cx,c.cy,c.rOut-len,deg),[x2,y2]=nisXY(c.cx,c.cy,c.rOut,deg);
      out+=`<line class="nis-tick${major?' maj':mid?' mid':''}${red?' red':''}" x1="${nisN(x1)}" y1="${nisN(y1)}" x2="${nisN(x2)}" y2="${nisN(y2)}"/>`;
      if(major){
        const [tx,ty]=nisXY(c.cx,c.cy,c.rNum,deg);
        nums+=`<text class="nis-num${red?' red':''}" x="${nisN(tx)}" y="${nisN(ty)}" style="font-size:${c.fs}px">${c.label(i/c.minorPer)}</text>`;
      }
    }
    if(c.redFrom!=null)out+=`<path class="nis-redarc" d="${nisArc(c.cx,c.cy,c.rOut+7,c.start+c.sweep*c.redFrom,c.start+c.sweep)}"/>`;
    if(c.band)out+=`<path class="nis-band" d="${nisArc(c.cx,c.cy,c.rOut+c.band,c.start,c.start+c.sweep)}"/>`;
    return out+nums;
  }
  const nisD=(cx,cy,r,cut)=>{const hw=Math.sqrt(Math.max(0,r*r-cut*cut));return `M${nisN(cx-hw)} ${nisN(cy+cut)} A${r} ${r} 0 1 1 ${nisN(cx+hw)} ${nisN(cy+cut)} Z`;};
  /* Face + two rings: brushed aluminium (350Z) and gunmetal with an amber accent line (G35). shape = circle or the flat-bottomed "D" of the tachometer window */
  function nisFaceMarkup(cx,cy,R,w,cut){
    const sh=(r,c)=>cut==null?`<circle cx="${cx}" cy="${cy}" r="${r}"`:`<path d="${nisD(cx,cy,r,c)}"`;
    const face=`${sh(R-w+.5,(cut||0)-w/2+.5)} fill="url(#nis-face)"/>`;
    const z=`<g class="nis-ring-z">${sh(R-w/2,cut)} fill="none" stroke="url(#nis-ring-al)" stroke-width="${w}" stroke-linejoin="round"/>`+
      `${sh(R-.5,(cut||0)+w/2-.5)} fill="none" stroke="#25272b" stroke-width="1"/>${sh(R-w+.5,(cut||0)-w/2+.5)} fill="none" stroke="#0d0d0f" stroke-width="1"/></g>`;
    const g=`<g class="nis-ring-g">${sh(R-w/2,cut)} fill="none" stroke="url(#nis-ring-gm)" stroke-width="${w}" stroke-linejoin="round"/>`+
      `${sh(R-.5,(cut||0)+w/2-.5)} fill="none" stroke="#050506" stroke-width="1"/>${sh(R-w+1.4,(cut||0)-w/2+1.4)} fill="none" class="nis-accent" stroke-width="1.6"/></g>`;
    return face+z+g;
  }
  function nisNeedleMarkup(id,cx,cy,L,wT,tail,startDeg){
    const p=pts=>pts.map(q=>q[0].toFixed(2)+','+q[1].toFixed(2)).join(' ');
    const z=[[-wT,tail],[-wT*.5,-L*.45],[0,-L],[wT*.5,-L*.45],[wT,tail]];                      // 350Z: sharp tapered blade
    const gw=wT*.62,sw=gw*.8,b=gw*.6,yb=-(L-sw/2-b);                                           // G35: slim blade, domed tip (outer tip lands exactly on L) + tail bulb
    const g=`M${(-gw).toFixed(2)} ${tail} L${(-b).toFixed(2)} ${yb.toFixed(2)} A${b.toFixed(2)} ${b.toFixed(2)} 0 0 1 ${b.toFixed(2)} ${yb.toFixed(2)} L${gw.toFixed(2)} ${tail} Z`;
    return `<g id="${id}" class="nis-needle" transform="rotate(${startDeg} ${cx} ${cy})"><g transform="translate(${cx} ${cy})">`+
      `<polygon class="nis-n-z" points="${p(z)}"/><path class="nis-n-g" d="${g}" stroke-width="${sw.toFixed(2)}"/><circle class="nis-n-g nis-n-bulb" cx="0" cy="${tail}" r="${(gw*1.5).toFixed(2)}"/></g></g>`;
  }
