    rpmScale:epGet('ep-rpm-scale'),speedScale:epGet('ep-speed-scale'),speedInner:epGet('ep-speed-inner'),turboScale:epGet('ep-turbo-scale'),nitroScale:epGet('ep-nitro-scale'),
