        <g transform="rotate(-20 500 210)"><rect x="300" y="-231" width="230" height="882" fill="url(#s2k-sh-band)"/><rect x="575" y="-231" width="40" height="882" fill="url(#s2k-sh-band)" opacity=".9"/><rect x="655" y="-231" width="14" height="882" fill="url(#s2k-sh-band)" opacity=".65"/></g>
