  /* speedometer scales: "game" = the same 0-400 km/h (0-250 mph) as every other analogue skin; "real" = the real car's dial (needle stops at the end) */
  const ccSpeedCfg=(realSweep,gameSweep,mphRealMax,kmhRealMax=180)=>(mph,real)=>real
    ?(mph?{max:mphRealMax,majorCount:mphRealMax/20,step:20,minorPer:4,midEvery:2,sweep:realSweep}:{max:kmhRealMax,majorCount:kmhRealMax/20,step:20,minorPer:4,midEvery:2,sweep:realSweep})
    :(mph?{max:250,majorCount:10,step:25,minorPer:5,midEvery:0,sweep:gameSweep}:{max:400,majorCount:10,step:40,minorPer:4,midEvery:2,sweep:gameSweep});

  const CC_IG_T={cx:322,cy:150,R:142,w:8,rOut:121,majLen:14,midLen:0,minLen:7,rNum:88,fs:23,rBand:129,bandW:6,start:-130,sweep:260,minorPer:5,midEvery:0,redNum:false};
  const CC_IG_S={cx:150,cy:150,R:142,w:8,rOut:121,majLen:14,midLen:9,minLen:6,rNum:90,fs:18.7,start:-125};
