      tick.className='rx7v2-tick'+(major?' major':'')+(fraction>=cfg.redFrac-1e-9?' redzone':'');
      tick.style.transform=`rotate(${deg}deg) translateY(${-cfg.needleRadius}px)`;
      tf.append(tick);
