  /* Silhouette of the faceplate: vertical-scan envelope of padded circles (the tach window is a flat-bottomed "D"),
     then concave creases between the dials are filled by a moving average (never removes area) so the outline flows like the real cluster. */
  function nisEnvelope(circles){
    const xmin=Math.min(...circles.map(c=>c.cx-c.r)),xmax=Math.max(...circles.map(c=>c.cx+c.r));
    const steps=Math.min(520,Math.max(130,Math.ceil((xmax-xmin)/3)));
    const top=[],bot=[],xs=[];
    for(let i=0;i<=steps;i++){
      const x=xmin+(xmax-xmin)*i/steps;let yT=Infinity,yB=-Infinity;
      for(const c of circles){
        const dx=x-c.cx;if(Math.abs(dx)>c.r)continue;
        const h=Math.sqrt(Math.max(0,c.r*c.r-dx*dx));
        yT=Math.min(yT,c.cy-h);yB=Math.max(yB,Math.min(c.cy+h,c.yMax===undefined?Infinity:c.yMax));
      }
      if(Number.isFinite(yT)){xs.push(x);top.push(yT);bot.push(yB);}
    }
    if(xs.length<4)return '';
    const avg=(arr,win)=>arr.map((_,i)=>{let sum=0,n=0;for(let k=-win;k<=win;k++){const j=i+k;if(j>=0&&j<arr.length){sum+=arr[j];n++;}}return sum/n;});
    const win=Math.max(6,Math.round(16*steps/Math.max(1,(xmax-xmin)/3)));
    const sT=avg(top,win),sB=avg(bot,win);
    const n=v=>Math.round(v*10)/10;
    const T=xs.map((x,i)=>[n(x),n(Math.min(top[i],sT[i]))]),B=xs.map((x,i)=>[n(x),n(Math.max(bot[i],sB[i]))]);
    return 'M '+T.map(p=>p.join(' ')).join(' L ')+' L '+B.reverse().map(p=>p.join(' ')).join(' L ')+' Z';
  }
  function nisLayout(){
    const P=prefix=>({dx:originValue(prefix+'OffsetX')+settings[prefix+'OffsetX'],dy:originValue(prefix+'OffsetY')+settings[prefix+'OffsetY'],s:settings[prefix+'SizePct']/100});
    const rpm=P('nissanRpm'),spd=P('nissanSpeed'),trb=P('nissanTurbo');
    const put=(el,o)=>{const v=`translate(${o.dx}px,${o.dy}px) scale(${o.s})`;if(el.style.transform!==v)el.style.transform=v;};
    put(nisUi.rpm,rpm);put(nisUi.speed,spd);put(nisUi.dual,trb);
    const L={cx:185+trb.dx,cy:245+trb.dy,r:140*trb.s},T={cx:500+rpm.dx,cy:205+rpm.dy,r:158*rpm.s,cut:110*rpm.s},S={cx:815+spd.dx,cy:245+spd.dy,r:140*spd.s};
    const mk=pad=>[{cx:L.cx,cy:L.cy,r:L.r+pad},{cx:T.cx,cy:T.cy,r:T.r+pad,yMax:T.cy+T.cut+pad},{cx:S.cx,cy:S.cy,r:S.r+pad}];
    const plate=nisEnvelope(mk(NIS_PAD)),bezel=nisEnvelope(mk(NIS_PAD+NIS_BZ));
    for(const el of nisUi.plate)if(el.getAttribute('d')!==plate)el.setAttribute('d',plate);
    for(const el of nisUi.bezel)if(el.getAttribute('d')!==bezel)el.setAttribute('d',bezel);
    if(nisUi.gcPath.getAttribute('d')!==bezel)nisUi.gcPath.setAttribute('d',bezel);
    // the two small round lamps / screw holes sit in the gaps between the dials
    const padded=mk(NIS_PAD);
    const topAt=x=>{let y=Infinity;for(const c of padded){const dx=x-c.cx;if(Math.abs(dx)<c.r)y=Math.min(y,c.cy-Math.sqrt(c.r*c.r-dx*dx));}return y;};
    const gaps=[[L.cx+L.r,T.cx-T.r],[T.cx+T.r,S.cx-S.r]];
    gaps.forEach((g,i)=>{
      const el=nisUi.holes[i],w=g[1]-g[0],x=(g[0]+g[1])/2,y=topAt(x)+30;
      if(w<12||!Number.isFinite(y)){el.style.display='none';return;}
      el.style.display='';
      const r=Math.min(6.5,w/2-1.5);
      el.setAttribute('cx',n2(x));el.setAttribute('cy',n2(y));el.setAttribute('r',n2(r));
    });
    function n2(v){return (Math.round(v*10)/10).toString();}
  }

