      if(!dk.photoLoaded){dk.photoLoaded=true;dkP.photo.src=DK_POLICE_IMG;}
      if(title!==undefined){dkP.main.textContent=title;dkP.sub.textContent=sub||"";dkP.main.classList.toggle("sm",Math.max(...title.split("\n").map(s=>s.length))>19);}
