  function dkShowBottle(kind){dkEl.beer.style.display=kind==="beer"?"":"none";dkEl.whisky.style.display=kind==="whisky"?"":"none";}
  function dkAskReset(){for(const b of dkP.btns)b.classList.remove("pick","dim");}
