  const FV_TITLES={home:"Frontvex",settings:"Settings",cars:"Cars HUD",colors:"Colors",wallpaper:"Wallpaper",effects:"Effects",driving:"Driving",status:"Status HUD",profiles:"Profiles",keys:"Shortcuts",phone:"Phone",markers:"Markers",clock:"Clock",calendar:"Calendar",weather:"Weather",contacts:"Contacts",messages:"Messages",updates:"Software Update",mycar:"My Car",racing:"Frontvex Racing"};
