  const fvRacing=globalThis.__frontvexRacing.mount(mget("fvRacing"),hudStorage,{close:()=>{if(menuOpen)toggleMenu(false);},isVisible:()=>phoneActive&&menuOpen&&fvView==="racing",city:()=>settings.markersCity,notify:msg=>showSaveToast(msg,false),raceNotice:(kind,sender,track)=>fvNotifications.raceNotice(kind,sender,track),inviteCount:racingInviteCount,viewFeed:on=>vfSet("racing",on)});
